import sys
from typing import List, Tuple

def read_vectors() -> List[Tuple[int, int]]:
    n = int(sys.stdin.readline().strip())
    vectors = []
    for _ in range(n):
        x, y = map(int, sys.stdin.readline().strip().split())
        vectors.append((x, y))
    return vectors

def compute_angle(v1: Tuple[int, int], v2: Tuple[int, int]) -> float:
    dot_product = v1[0] * v2[0] + v1[1] * v2[1]
    norm_v1 = (v1[0]**2 + v1[1]**2)**0.5
    norm_v2 = (v2[0]**2 + v2[1]**2)**0.5
    cos_angle = dot_product / (norm_v1 * norm_v2)
    angle = min(cos_angle, -cos_angle)
    return abs(angle)

def find_minimal_angle_pair(vectors: List[Tuple[int, int]]) -> Tuple[int, int]:
    min_angle = float('inf')
    min_pair = (0, 0)
    n = len(vectors)
    for i in range(n):
        for j in range(i + 1, n):
            angle = compute_angle(vectors[i], vectors[j])
            if angle < min_angle:
                min_angle = angle
                min_pair = (i + 1, j + 1)
    return min_pair

def main():
    vectors = read_vectors()
    result = find_minimal_angle_pair(vectors)
    print(result[0], result[1])

if __name__ == "__main__":
    main()
